#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_TOKEN_LEN 256
#define MAX_SESSIONS 64
#define SESSION_DATA_SIZE 1024

typedef struct {
    char token[MAX_TOKEN_LEN];
    char data[SESSION_DATA_SIZE];
    int data_len;
    time_t created;
    int active;
} Session;

static Session g_sessions[MAX_SESSIONS];
static int g_session_count = 0;

/* Constant-time comparison to prevent timing attacks */
static int secure_compare(const char *a, const char *b, size_t len) {
    volatile unsigned char result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= (unsigned char)a[i] ^ (unsigned char)b[i];
    }
    return result == 0;
}

/* Generate a random token using /dev/urandom */
static int generate_token(char *buf, size_t len) {
    FILE *f = fopen("/dev/urandom", "r");
    if (!f) return -1;
    static const char charset[] = "abcdefghijklmnopqrstuvwxyz0123456789";
    unsigned char rand_bytes[MAX_TOKEN_LEN];
    if (fread(rand_bytes, 1, len, f) != len) {
        fclose(f);
        return -1;
    }
    fclose(f);
    for (size_t i = 0; i < len; i++) {
        buf[i] = charset[rand_bytes[i] % (sizeof(charset) - 1)];
    }
    buf[len] = '\0';
    return 0;
}

/* Validate that offset and length are within bounds */
static int validate_bounds(int offset, int length, int buffer_size) {
    /* Ensure offset is non-negative */
    if (offset < 0) return 0;
    /* Ensure length is non-negative */
    if (length < 0) return 0;
    /* Ensure offset + length doesn't exceed buffer */
    if (offset + length > buffer_size) return 0;
    return 1;
}

int create_session(const char *initial_data, int data_len) {
    if (g_session_count >= MAX_SESSIONS) return -1;
    if (data_len < 0 || data_len > SESSION_DATA_SIZE) return -1;

    Session *s = &g_sessions[g_session_count];
    if (generate_token(s->token, 32) != 0) return -1;

    memcpy(s->data, initial_data, data_len);
    s->data_len = data_len;
    s->created = time(NULL);
    s->active = 1;
    g_session_count++;

    printf("Session created: %s\n", s->token);
    return g_session_count - 1;
}

Session* find_session(const char *token) {
    for (int i = 0; i < g_session_count; i++) {
        if (g_sessions[i].active && 
            secure_compare(g_sessions[i].token, token, 32)) {
            return &g_sessions[i];
        }
    }
    return NULL;
}

/* Update session data at a specific offset */
int update_session_data(const char *token, int offset, const char *new_data, int length) {
    Session *s = find_session(token);
    if (!s) return -1;

    /* Validate the write bounds */
    if (!validate_bounds(offset, length, SESSION_DATA_SIZE)) {
        fprintf(stderr, "Bounds check failed: offset=%d, length=%d\n", offset, length);
        return -1;
    }

    memcpy(s->data + offset, new_data, length);

    /* Update data_len if we extended the data */
    if (offset + length > s->data_len) {
        s->data_len = offset + length;
    }

    return 0;
}

/* Read session data from a specific offset */
int read_session_data(const char *token, int offset, int length, char *out_buf) {
    Session *s = find_session(token);
    if (!s) return -1;

    /* Validate the read bounds */
    if (!validate_bounds(offset, length, SESSION_DATA_SIZE)) {
        return -1;
    }

    memcpy(out_buf, s->data + offset, length);
    return length;
}

/* Append data to session, with a computed remaining capacity */
int append_session_data(const char *token, const char *new_data, int length) {
    Session *s = find_session(token);
    if (!s) return -1;

    int remaining = SESSION_DATA_SIZE - s->data_len;
    if (length > remaining) {
        fprintf(stderr, "Append would overflow: length=%d, remaining=%d\n", length, remaining);
        return -1;
    }
    if (length < 0) return -1;

    memcpy(s->data + s->data_len, new_data, length);
    s->data_len += length;
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <command> [args...]\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "create") == 0) {
        if (argc < 3) return 1;
        return create_session(argv[2], strlen(argv[2]));
    } else if (strcmp(argv[1], "update") == 0) {
        if (argc < 6) return 1;
        const char *token = argv[2];
        int offset = atoi(argv[3]);
        const char *data = argv[4];
        int length = atoi(argv[5]);
        return update_session_data(token, offset, data, length);
    } else if (strcmp(argv[1], "read") == 0) {
        if (argc < 5) return 1;
        const char *token = argv[2];
        int offset = atoi(argv[3]);
        int length = atoi(argv[4]);
        char buf[SESSION_DATA_SIZE];
        int n = read_session_data(token, offset, length, buf);
        if (n > 0) {
            fwrite(buf, 1, n, stdout);
            printf("\n");
        }
        return n < 0 ? 1 : 0;
    } else if (strcmp(argv[1], "append") == 0) {
        if (argc < 5) return 1;
        const char *token = argv[2];
        const char *data = argv[3];
        int length = atoi(argv[4]);
        return append_session_data(token, data, length);
    }

    return 0;
}
